// Trick executive loop demo (simulated model)
var jobs=['env','dynamics','gnc','io'], dt=0.01, t=0;
for(var s=0;s<3;s++){t+=dt;console.log('t='+t.toFixed(2)+'s scheduled: '+jobs.join(','));}
console.log('Trick executive: '+jobs.length+' jobs @ '+dt+'s');

// S_define-style config demo (simulated model)
var sdef={models:['gravity','aero','mass'],jobs:{'dynamics.pre':['gravity'],'dynamics.post':['aero']},rate:100};
console.log('models: '+sdef.models.join(','));
console.log('jobs: '+Object.keys(sdef.jobs).join(',')+' @ '+sdef.rate+'Hz');

// PID control demo (simulated model)
var kp=1.2, ki=0.1, kd=0.3, err=10, integ=0, prev=10;
for(var i=0;i<5;i++){integ+=err;var d=err-prev;var u=kp*err+ki*integ+kd*d;prev=err;err*=0.6;console.log('step '+i+': u='+u.toFixed(2)+' err='+err.toFixed(2));}
console.log('GNC loop converging');

// Monte Carlo spread demo (simulated model)
var n=200, sum=0, sum2=0;
for(var i=0;i<n;i++){var x=(Math.sin(i*12.9898)*43758.5453)%1;var v=100+8*(x-Math.floor(x)-0.5)*2;sum+=v;sum2+=v*v;}
var mean=sum/n, sd=Math.sqrt(sum2/n-mean*mean);
console.log(n+' runs: mean='+mean.toFixed(2)+' sd='+sd.toFixed(2));
console.log('3-sigma band: '+(mean-3*sd).toFixed(1)+'..'+(mean+3*sd).toFixed(1));

// HLA federation demo (simulated model)
var feds=['vehicle','ground','trainer'], t=0;
for(var s=0;s<3;s++){t+=1;console.log('t='+t+'s federates synced: '+feds.join(','));}
console.log('TrickHLA: '+feds.length+' federates in step');

// Data recording demo (simulated model)
var rec=[];
for(var i=0;i<5;i++){rec.push({t:i,v:(100-i*7)});}
console.log('recorded '+rec.length+' samples:');
for(var i=0;i<rec.length;i++){console.log(' t='+rec[i].t+' v='+rec[i].v);}
console.log('TrickView would plot v(t) live');

// Real-time frame demo (simulated model)
var frames=5, dt=0.02, over=0;
for(var f=0;f<frames;f++){var work=0.015+((f*13)%5)*0.001;if(work>dt)over++;console.log('frame '+f+': work='+work.toFixed(3)+'s '+(work>dt?'OVERRUN':'ok'));}
console.log(over+'/'+frames+' overruns');

// Input-file case matrix demo (simulated model)
var cases=[['nominal',7000,0],['heavy',7000,500],['engine-out',7000,-1]];
for(var i=0;i<cases.length;i++){console.log('case '+cases[i][0]+': r='+cases[i][1]+' fault='+cases[i][2]);}
console.log(cases.length+' cases, one compiled sim');

// Complementary filter demo (simulated model)
var est=0, alpha=0.9;
var meas=[10.5,9.2,10.1,9.8,10.0];
for(var i=0;i<meas.length;i++){est=alpha*est+(1-alpha)*meas[i];console.log('meas '+meas[i]+' -> est '+est.toFixed(2));}
console.log('fused estimate: '+est.toFixed(2));

// EDL altitude profile demo (simulated model)
var alt=120000, vs=0;
for(var i=0;i<6;i++){vs=Math.min(vs+1500,11000);alt-=vs*10;if(alt<0)alt=0;console.log('t+'+(i*10)+'s alt='+(alt/1000).toFixed(1)+'km v='+vs+'m/s');}
console.log('EDL profile simulated');

// Failure injection demo (simulated model)
var thrusters=[1,1,1,1], failAt=2;
for(var i=0;i<4;i++){if(i===failAt)thrusters[2]=0;var tot=thrusters.reduce(function(a,b){return a+b;},0);console.log('step '+i+': thrust='+tot+'/4 '+(tot<4?'FAULT':'ok'));}
console.log('FDIR would reallocate to healthy thrusters');

// Verification trace demo (simulated model)
var reqs=[['GNC-001',120],['GNC-002',300],['PROP-010',500]], tot=0;
for(var i=0;i<reqs.length;i++){tot+=reqs[i][1];console.log(reqs[i][0]+': '+reqs[i][1]+' cases');}
console.log('campaign: '+tot+' cases trace to requirements');

// Orion-class entry check demo (simulated model)
var v=11000, gamma=-6.5;
for(var i=0;i<4;i++){v-=2200;gamma+=1.2;console.log('entry t+'+(i*60)+'s v='+v+' m/s gamma='+gamma.toFixed(1)+'deg');}
console.log('entry corridor held (simulated)');

// TrickView binding demo (simulated model)
var vars={altitude:120000,velocity:7800,fuel:98};
for(var k in vars){console.log('display bound: '+k+' = '+vars[k]);}
console.log(Object.keys(vars).length+' live widgets');

// Full Trick pipeline demo (simulated model)
var pipe=['models','S_define','generate','input files','monte carlo','record','trickview','evidence'];
for(var i=0;i<pipe.length;i++){console.log('stage '+(i+1)+'/'+pipe.length+': '+pipe[i]);}
console.log('Trick pipeline complete');
